test('update sets value optimistically', async () => {
  const { result } = renderHook(() => useOptimistic(0));
  let pending!: Promise<void>;
  act(() => { pending = result.current.update(99, () => Promise.resolve()); });
  expect(result.current.value).toBe(99);
  await act(async () => { await pending; });
});

test('isUpdating is true while async fn is pending', async () => {
  const { result } = renderHook(() => useOptimistic(0));
  let resolve!: () => void;
  const promise = new Promise<void>(r => { resolve = r; });
  act(() => { result.current.update(1, () => promise); });
  expect(result.current.isUpdating).toBe(true);
  await act(async () => resolve());
  expect(result.current.isUpdating).toBe(false);
});

test('value stays updated after successful async fn', async () => {
  const { result } = renderHook(() => useOptimistic('a'));
  await act(async () => result.current.update('b', () => Promise.resolve()));
  expect(result.current.value).toBe('b');
});

