import { useState, useRef } from 'react';

export function useOptimistic<T>(initial: T) {
  const [value, setValue] = useState<T>(initial);
  const [isUpdating, setIsUpdating] = useState(false);
  const committedRef = useRef<T>(initial);

  const update = async (newVal: T, asyncFn: () => Promise<void>) => {
    const previous = committedRef.current;
    setValue(newVal);
    setIsUpdating(true);
    try {
      await asyncFn();
      committedRef.current = newVal;
    } catch (err) {
      setValue(previous);
      throw err;
    } finally {
      setIsUpdating(false);
    }
  };

  return { value, update, isUpdating };
}
